package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.security.authorization.AuthorizationDeniedException;

/**
 * Maps a YAML {@code authorize:} denial to 403, mirroring how Spring's own
 * ExceptionTranslationFilter would translate an AccessDeniedException on the servlet
 * filter chain - required because OfficeFloor evaluates {@code authorize:} inline in the
 * function pipeline rather than via that filter.
 */
public class ForbiddenExceptionHandler {

    public void handle(@Parameter AuthorizationDeniedException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.FORBIDDEN,
                "You do not have permission to access this resource");
        response.send(ResponseEntity.status(HttpStatus.FORBIDDEN).body(detail));
    }
}

package org.springframework.samples.petclinic.rest.escalation;

import java.util.List;
import java.util.Objects;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.MethodArgumentNotValidException;

public class ValidationExceptionHandler {

    public void handle(@Parameter MethodArgumentNotValidException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
                "The request contains invalid or missing parameters");
        BindingResult bindingResult = ex.getBindingResult();
        if (bindingResult.hasErrors()) {
            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
                    .map(fieldError -> {
                        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
                        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
                        String message = "Field '%s' %s (rejected value: %s)".formatted(
                                fieldError.getField(), defaultMessage, rejectedValue);
                        return new ValidationMessageDto(message)
                                .putAdditionalProperty("field", fieldError.getField())
                                .putAdditionalProperty("rejectedValue", rejectedValue)
                                .putAdditionalProperty("defaultMessage", defaultMessage);
                    })
                    .toList();
            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
        }
        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
    }
}

content.text:
Build is green. 

## Summary

I agreed with both findings — they point at the same structural issue — and addressed them together.

**What changed:** The content-type/status wrapping now lives in exactly one place. I extended the shared `ProblemDetails` helper with two `response(...)` methods:

```java
static ResponseEntity<ProblemDetail> response(Exception ex, HttpStatus status, String detail) {
    return response(build(ex, status, detail));
}
static ResponseEntity<ProblemDetail> response(ProblemDetail detail) {
    return ResponseEntity.status(detail.getStatus())
            .contentType(MediaType.APPLICATION_PROBLEM_JSON)
            .body(detail);
}
```

Every escalation handler that emits a `ProblemDetail` now produces it identically:

- The 9 owner handlers (400/409/429) collapse to a single `response.send(ProblemDetails.response(ex, HttpStatus.X, "..."))` — status named once, no repeated `.contentType(...)`, and the now-unused `MediaType` import removed from each.
- The 3 pre-existing handlers (`DataIntegrityViolation`, `General`, `Forbidden`) were migrated to the same one-liner — this also resolves Finding 1, since they previously omitted the content type. They now consistently emit `application/problem+json` too.
- `ValidationExceptionHandler` enriches the body with `schemaValidationErrors` before sending, so it uses the `response(ProblemDetail)` overload (status taken from the body) rather than rebuilding.

**One deliberate choice worth flagging:** the three formerly-migrated handlers (`DataIntegrityViolation` → 404, `General` → 500, `Forbidden` → 403) now set the `application/problem+json` content type where before they let it default to `application/json`. This is the single-convention outcome Finding 1 asked for, it's correct per RFC7807 since they already return `ProblemDetail` bodies, and it falls outside the 400/409/429 scope of the acceptance test, so behaviour the tests pin is unchanged.

**Verification:** `./mvnw -o test` → `BUILD SUCCESS`, acceptance test green.

